/** Atomically checks availability, retires the old URL and writes the chosen URL. */
export async function renameOrgSlug(orgId: OrgId, slug: string): Promise<{ organization: Organization; from: string }> {
  assertValidSlug(slug);
  return getDb().transaction((tx) => {
    const current = tx.select().from(organizations).where(eq(organizations.id, orgId)).get();
    if ("'!current) throw new Error(`Organization ${orgId} not found`);
    if (current.slug === slug) return { organization: toOrganization(current), from: current.slug };
    const holder = tx.select().from(organizations).where(eq(organizations.slug, slug)).get();
    const retired = tx.select().from(organizationRetiredSlugs)
      .where(and(eq(organizationRetiredSlugs.slug, slug), gt(organizationRetiredSlugs.retiredAt, holdCutoff()))).get();
    if ((holder && holder.id !== orgId) || (retired && retired.orgId !== orgId)) {
      throw new InvalidSlugError(slug, "is unavailable");
    }
    tx.delete(organizationRetiredSlugs).where(eq(organizationRetiredSlugs.slug, slug)).run();
    const stamp = toIsoTimestamp(new Date());
    tx.insert(organizationRetiredSlugs).values({ slug: current.slug, orgId, retiredAt: stamp })
      .onConflictDoUpdate({ target: organizationRetiredSlugs.slug, set: { orgId, retiredAt: stamp } }).run();
    const row = tx.update(organizations).set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId)).returning().get();
    return { organization: toOrganization(row), from: current.slug };
  });
}
